#!/bin/sh
# يشغّل كل الاختبارات ويعتمد رمز الخروج لا عدّ كلمة FAIL فقط: sh test/all.sh
cd "$(dirname "$0")/.." || exit 1
bad=0
for t in steward steward-ui team-promotion team-promotion-ui wage-mode wage-mode-ui regional-office regional-office-ui vault-opportunity vault-opportunity-ui vault-reserve vault-panel-ui vault-year batch-selection vault-draw vault-draw-ui runner-isolation early-qard-mentor-ui early-qard-deal-ui early-qard-ui early-qard early-qard-quote trade-restart-ui trade-restart asset-learning-ui city-assets-ui city-assets asset-sale-ui reduced-motion-ui haptics-ui asset-facilities asset-sale asset-quote payments payments-ui obligations-alert-ui obligations obligations-ui idle-ui lazy-assets city-scenes cargo-products-ui backup-ui ui-audit deals-fold-ui longtext-ui facility-ui icons world-map map-ui navigation characters hud screens market lords qty tutorial maplabels learn learnengine journey journey-ui guided guided-growth guided-mastery guided-graduation guided-qard lore lore-ui start babylon babylon-ui dev header-ledger zakat bosses currency shops sells abroad save cover numerals update market2 market2-ui staff staff-ui rent rent-ui goods animals livestock-market manager-pricing farm-add lesson-points perk-tree herd herd-ui breed farm farm-ui salem-ui breeds sex hybrid hybrid-ui butcher butcher-ui haggle haggle-ui factories factories-ui sound sound-ui dialogs plaza-ui shocks shocks-ui savecode savecode-ui captains captains-ui diff-ui typing-ui mounts insurance stage5a stage5a-ui pstory pstory-ui seasons rival stage5b-ui caravan-anim achievements achievements-ui cards cards-ui side-lessons-ui lesson-lock zakat-lesson-ui rank-slots butcher-sheet livestock-tabs-ui finance finance-ui cities-ui freeplay freeplay-ui autopilot autopilot-finance autopilot-graduation autopilot-year overlay-ui typing-salem mini-ui names store-ui haggle-culture outcome-ui silver silver-ui sea sea-stories sea-ui pace pace-ui routes holy holy-ui mjlis mjlis-ui zakat-an zakat-an-ui defect defect-ui hud-big calendar calendar-ui wage wage-ui guide guide-ui terms story-ui textlint tablet-ui tripprep-ui calm-ui arrival-ui receipt-ui reasons-ui scrollmem-ui help-ui office-ui insights-ui world-ui overlap-ui planner-ui legs-ui breedlabel-ui fxmanual fxmanual-ui poultry-sex poultry-ui art-ui enrich topclose-ui baraka route-ui shopreport shopsetup-ui howto-ui fleetreport fleetrep-ui alerts-ui shopecon wealth sectors aging aging-ui aging-art lifecycle lifecycle-ui climate climate-econ climate-ui; do
  timeout 180 node test/$t.test.js > /tmp/t_$t.out 2>&1; code=$?
  if [ $code -ne 0 ] || grep -qE "^FAIL|ERRORS:|pageerror" /tmp/t_$t.out; then echo "✗ $t (exit $code)"; grep -E "^FAIL|ERRORS|pageerror|Error" /tmp/t_$t.out | head -3; bad=1; else echo "✓ $t"; fi
done
exit $bad
